def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Simple approach: find first differing position and what needs to change
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion at the end
    if s_in[:min_len] == s_out[:min_len] and len(s_in) != len(s_out):
        if len(s_in) < len(s_out):
            # Insertion at the end
            return (s_in[min_len:], s_out[min_len:], min_len)
        else:
            # Deletion at the end  
            return (s_in[min_len:], '', min_len)

    # Check for substitution or deletion/insertion in middle
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Find the longest matching prefix and suffix
            # For simplicity, let's assume single character changes or simple patterns
            # We'll handle more complex cases as we go

            # Check if we're replacing a substring
            # Try to find what part of s_in should be replaced with what in s_out
            for length in range(1, min(4, len(s_in) + 1)):  # max 3 char patterns
                if i + length <= len(s_in):
                    old_sub = s_in[i:i+length]
                    # Check if this pattern matches in s_out
                    if s_out.find(old_sub, i) != -1:
                        # Try to see if we can find a match
                        new_sub = s_out[i:i+length] if i + length <= len(s_out) else s_out[i:]
                        return (old_sub, new_sub, i)

            # Default case - single character change
            return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of other
    if len(s_in) < len(s_out):
        # Insertion
        return (s_in[min_len:], s_out[min_len:], min_len)
    elif len(s_in) > len(s_out):
        # Deletion
        return (s_in[min_len:], '', min_len)
    else:
        return ('', '', -1)  # No difference

# Analyze each changed pair
for idx, s_in, s_out in changed:
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"'{s_in}' -> '{s_out}': replace '{old_sub}' with '{new_sub}' at position {pos}")

